using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // EF Core 9 Cosmos provider removed synchronous I/O by default.
        // Opt back in while migrating call sites to async.
        optionsBuilder.EnableThreadSafetyChecks(false);
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1 — Discriminator property renamed from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator"; keep that so they remain readable
        // and direct SQL queries (WHERE c.Discriminator = ...) keep working.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2 — id format changed from "Product|123" to just "123".
        // Existing documents use the old format; preserve it so EF can find them.
        modelBuilder.Entity<Product>().HasIdProperty(p => p.Id, IdValueGeneration.WhenEmpty)
            .Property(p => p.Id)
            .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

